    def kill_existing_chrome_processes(self):
        """Kill any existing Chrome/Chromium processes before starting browser."""
        try:
            import subprocess
            import signal
            
            logger.info("🔍 Checking for existing Chrome processes...")
            
            # Find Chrome/Chromium processes
            try:
                result = subprocess.run(
                    ['pgrep', '-f', 'chrome|chromium'],
                    capture_output=True,
                    text=True,
                    timeout=5
                )
                
                if result.returncode == 0 and result.stdout.strip():
                    pids = result.stdout.strip().split('\n')
                    logger.info(f"🧹 Found {len(pids)} existing Chrome process(es), killing them...")
                    
                    for pid in pids:
                        try:
                            pid_int = int(pid.strip())
                            os.kill(pid_int, signal.SIGTERM)
                            logger.info(f"   └─ Killed Chrome process: {pid_int}")
                        except (ValueError, ProcessLookupError, PermissionError) as e:
                            logger.debug(f"   └─ Could not kill PID {pid}: {e}")
                    
                    # Wait for processes to terminate
                    import time
                    time.sleep(2)
                    logger.info("✅ Chrome processes terminated")
                else:
                    logger.info("✅ No existing Chrome processes found")
                    
            except FileNotFoundError:
                logger.debug("pgrep not available, skipping process check")
            except Exception as e:
                logger.warning(f"⚠️ Failed to check for Chrome processes: {e}")
                
        except Exception as e:
            logger.warning(f"⚠️ Chrome process cleanup error: {e}")
    
